export const FALLBACK_ROLE = 'civilian';

export function catalogTemplatesForRole(role) {
  const r = String(role || '').toLowerCase();
  if (PHONE_FILE_CATALOG[r]) return PHONE_FILE_CATALOG[r];
  if (r === 'разработчик' || r === 'developer') return PHONE_FILE_CATALOG.developer || PHONE_FILE_CATALOG[FALLBACK_ROLE] || [];
  return PHONE_FILE_CATALOG[FALLBACK_ROLE] || Object.values(PHONE_FILE_CATALOG)[0] || [];
}

export function fillFilePlaceholders(text, phone, regionName) {
  const s = String(text || '');
  const name = phone?.ownerName || 'Unknown';
  const id = phone?.id || 'PH-????';
  const region = regionName || phone?.regionId || '—';
  const date = new Date().toISOString().slice(0, 10);
  return s
    .replaceAll('{NPC_NAME}', name)
    .replaceAll('{PHONE_ID}', id)
    .replaceAll('{REGION}', region)
    .replaceAll('{DATE}', date);
}
